const items = $input.all();
const rows = items.map(i => i.json);

// Dynamic pivot: group by first column, aggregate numeric columns
if (rows.length === 0) return [{ json: { error: 'No data found' } }];

const keys = Object.keys(rows[0]);
const groupKey = keys[0];
const numericKeys = keys.filter(k => k !== groupKey && !isNaN(Number(rows[0][k])));

const groups = {};
for (const row of rows) {
  const gVal = row[groupKey] || 'Unknown';
  if (!groups[gVal]) groups[gVal] = { [groupKey]: gVal, _count: 0 };
  groups[gVal]._count++;
  for (const nk of numericKeys) {
    const val = Number(row[nk]) || 0;
    groups[gVal][`${nk}_sum`] = (groups[gVal][`${nk}_sum`] || 0) + val;
    groups[gVal][`${nk}_values`] = groups[gVal][`${nk}_values`] || [];
    groups[gVal][`${nk}_values`].push(val);
  }
}

const pivotRows = Object.values(groups).map(g => {
  const result = { [groupKey]: g[groupKey], count: g._count };
  for (const nk of numericKeys) {
    result[`${nk}_sum`] = g[`${nk}_sum`];
    result[`${nk}_avg`] = Math.round((g[`${nk}_sum`] / g._count) * 100) / 100;
  }
  return result;
});

return pivotRows.map(r => ({ json: r }));

